<link href="https://fonts.googleapis.com/css2?family=DM+Sans:ital,opsz,wght@0,9..40,100..1000;1,9..40,100..1000&family=JetBrains+Mono:wght@400;500;600&display=swap" rel="stylesheet">
<style>
:root {
  --blue: #3861FB;
  --blue-hover: #2b4fd6;
  --blue-light: #e8ecff;
  --navy: #0D1421;
  --navy-light: #1a2332;
  --gray-50: #f8f9fb;
  --gray-100: #f0f1f5;
  --gray-200: #e2e4ea;
  --gray-300: #cfd2db;
  --gray-400: #a1a7b8;
  --gray-500: #808A9D;
  --gray-600: #5a6275;
  --gray-700: #3d4458;
  --gray-800: #252a3a;
  --gray-900: #0D1421;
  --green: #16c784;
  --green-bg: #e6f9f2;
  --red: #ea3943;
  --red-bg: #fde8e9;
  --white: #ffffff;
  --shadow-sm: 0 1px 2px rgba(13,20,33,0.06);
  --shadow-md: 0 4px 12px rgba(13,20,33,0.08);
  --shadow-lg: 0 8px 24px rgba(13,20,33,0.12);
  --radius-sm: 6px;
  --radius-md: 10px;
  --radius-lg: 14px;
  --font-sans: 'DM Sans', system-ui, sans-serif;
  --font-mono: 'JetBrains Mono', monospace;
  --transition: 0.2s ease;
}

*, *::before, *::after { box-sizing: border-box; margin: 0; padding: 0; }

html { font-size: 14px; scroll-behavior: smooth; }
body {
  font-family: var(--font-sans);
  color: var(--navy);
  background: var(--gray-50);
  line-height: 1.5;
  -webkit-font-smoothing: antialiased;
  -moz-osx-font-smoothing: grayscale;
  min-height: 100vh;
}

/* Typography */
.tabular { font-variant-numeric: tabular-nums; font-family: var(--font-mono); }
.price { font-family: var(--font-mono); font-weight: 500; }
a { color: var(--blue); text-decoration: none; }
a:hover { color: var(--blue-hover); }

/* Layout */
.container { max-width: 1320px; margin: 0 auto; padding: 0 20px; }
.section-padding { padding: 0 0 40px; }

/* NAVIGATION */
.nav {
  background: var(--white);
  border-bottom: 1px solid var(--gray-200);
  position: sticky; top: 0; z-index: 100;
}
.nav-inner {
  display: flex; align-items: center; gap: 24px;
  height: 56px;
}
.nav-logo {
  font-size: 1.25rem; font-weight: 700;
  color: var(--navy); white-space: nowrap;
  display: flex; align-items: center; gap: 8px;
}
.nav-logo .logo-icon {
  width: 28px; height: 28px;
  background: var(--blue); border-radius: var(--radius-sm);
  display: flex; align-items: center; justify-content: center;
  color: white; font-size: 14px; font-weight: 700;
}
.nav-links {
  display: flex; align-items: center; gap: 4px;
  list-style: none; flex: 1;
}
.nav-links > li { position: relative; }
.nav-links > li > a, .nav-links > li > button {
  display: flex; align-items: center; gap: 4px;
  padding: 8px 12px; border-radius: var(--radius-sm);
  color: var(--gray-600); font-size: 0.875rem; font-weight: 500;
  background: none; border: none; cursor: pointer;
  font-family: var(--font-sans);
}
.nav-links > li > a:hover, .nav-links > li > button:hover { color: var(--navy); background: var(--gray-100); }
.nav-cta { display: flex; align-items: center; gap: 10px; margin-left: auto; }
.btn {
  display: inline-flex; align-items: center; gap: 6px;
  padding: 8px 16px; border-radius: var(--radius-sm);
  font-size: 0.875rem; font-weight: 600; cursor: pointer;
  font-family: var(--font-sans);
  border: none; transition: var(--transition);
  white-space: nowrap;
}
.btn-ghost { background: transparent; color: var(--gray-600); border: 1px solid var(--gray-300); }
.btn-ghost:hover { background: var(--gray-100); color: var(--navy); }
.btn-primary { background: var(--blue); color: white; }
.btn-primary:hover { background: var(--blue-hover); }

/* TOP METRICS BAR */
.metrics-bar {
  background: var(--white);
  border-bottom: 1px solid var(--gray-200);
}
.metrics-grid {
  display: grid; grid-template-columns: repeat(4, 1fr);
  gap: 0; padding: 16px 0;
}
.metric-card {
  padding: 12px 20px;
  border-right: 1px solid var(--gray-200);
}
.metric-card:last-child { border-right: none; }
.metric-label {
  font-size: 0.75rem; color: var(--gray-500); font-weight: 500;
  text-transform: uppercase; letter-spacing: 0.5px;
  margin-bottom: 4px;
}
.metric-value {
  font-size: 1.25rem; font-weight: 700; color: var(--navy);
  font-family: var(--font-mono);
}
.metric-change { font-size: 0.8rem; margin-top: 2px; }
.metric-change.up { color: var(--green); }
.metric-change.down { color: var(--red); }
.metric-sub {
  font-size: 0.8rem; color: var(--gray-500); margin-top: 2px;
}

/* PROMO BANNER */
.promo-bar {
  background: var(--blue);
  color: white;
  position: relative;
  overflow: hidden;
}
.promo-inner {
  display: flex; align-items: center; justify-content: center;
  padding: 10px 40px; min-height: 40px;
  gap: 12px;
}
.promo-text { font-size: 0.875rem; font-weight: 500; text-align: center; }
.promo-dot { width: 6px; height: 6px; border-radius: 50%; background: rgba(255,255,255,0.5); }
.promo-dot.active { background: white; }
.promo-dots { display: flex; gap: 8px; align-items: center; }
.promo-nav {
  position: absolute; top: 50%; transform: translateY(-50%);
  background: rgba(255,255,255,0.2); border: none; color: white;
  width: 28px; height: 28px; border-radius: 50%; cursor: pointer;
  display: flex; align-items: center; justify-content: center;
  font-size: 14px; transition: var(--transition);
}
.promo-nav:hover { background: rgba(255,255,255,0.35); }
.promo-nav.prev { left: 16px; }
.promo-nav.next { right: 16px; }

/* AI ALERTS */
.ai-bar {
  background: var(--white);
  border-bottom: 1px solid var(--gray-200);
}
.ai-inner {
  display: flex; align-items: center; gap: 16px;
  padding: 10px 0; flex-wrap: wrap;
}
.ai-label {
  display: flex; align-items: center; gap: 6px;
  font-size: 0.8rem; font-weight: 600; color: var(--navy);
  white-space: nowrap;
}
.ai-label svg { width: 16px; height: 16px; color: var(--blue); }
.ai-topic {
  font-size: 0.875rem; color: var(--gray-700);
  border-right: 1px solid var(--gray-300); padding-right: 16px;
  white-space: nowrap;
}
.ai-chips {
  display: flex; gap: 6px; flex-wrap: wrap;
}
.ai-chip {
  padding: 5px 12px; border-radius: 20px; font-size: 0.75rem;
  background: var(--gray-100); color: var(--gray-600); border: 1px solid var(--gray-200);
  cursor: pointer; transition: var(--transition); font-family: var(--font-sans);
  white-space: nowrap;
}
.ai-chip:hover { background: var(--blue-light); color: var(--blue); border-color: var(--blue); }

/* TAB BARS */
.tab-bar {
  background: var(--white);
  border-bottom: 1px solid var(--gray-200);
  padding: 0;
}
.tab-bar-inner {
  display: flex; align-items: center; gap: 2px;
  overflow-x: auto; -webkit-overflow-scrolling: touch;
  scrollbar-width: none;
}
.tab-bar-inner::-webkit-scrollbar { display: none; }
.tab-btn {
  padding: 12px 18px; font-size: 0.85rem; font-weight: 500;
  color: var(--gray-500); background: none; border: none;
  border-bottom: 2px solid transparent; cursor: pointer;
  font-family: var(--font-sans); transition: var(--transition);
  white-space: nowrap;
}
.tab-btn:hover { color: var(--navy); }
.tab-btn.active { color: var(--blue); border-bottom-color: var(--blue); }
.tab-btn .tab-count {
  font-size: 0.7rem; background: var(--gray-200); color: var(--gray-500);
  padding: 1px 6px; border-radius: 10px; margin-left: 4px;
}
.tab-btn.active .tab-count { background: var(--blue-light); color: var(--blue); }

/* INDEX TRACKER */
.index-tracker {
  background: var(--gray-50);
  border-bottom: 1px solid var(--gray-200);
}
.index-row {
  display: flex; align-items: center; gap: 24px;
  padding: 12px 0; font-size: 0.85rem;
}
.index-badge {
  background: var(--blue); color: white;
  padding: 3px 10px; border-radius: 4px; font-size: 0.7rem;
  font-weight: 700; white-space: nowrap;
}
.index-name { font-weight: 600; color: var(--navy); white-space: nowrap; }
.index-symbol { color: var(--gray-500); font-size: 0.8rem; }
.index-price { font-family: var(--font-mono); font-weight: 600; color: var(--navy); }
.index-changes { display: flex; gap: 16px; }
.index-change { font-family: var(--font-mono); font-size: 0.8rem; font-weight: 500; }
.index-change.up { color: var(--green); }
.index-change.down { color: var(--red); }

/* TABLE SECTION */
.table-section {
  background: var(--white);
  border: 1px solid var(--gray-200);
  border-radius: var(--radius-lg);
  margin-top: 20px;
  overflow: hidden;
}
.table-header {
  display: flex; align-items: center; justify-content: space-between;
  padding: 16px 20px; border-bottom: 1px solid var(--gray-200);
  flex-wrap: wrap; gap: 12px;
}
.table-title {
  font-size: 1.1rem; font-weight: 700; color: var(--navy);
}
.table-controls { display: flex; gap: 8px; align-items: center; flex-wrap: wrap; }
.sort-select {
  padding: 7px 12px; border: 1px solid var(--gray-300); border-radius: var(--radius-sm);
  font-size: 0.8rem; color: var(--gray-700); background: var(--white);
  cursor: pointer; font-family: var(--font-sans);
}
.ctrl-btn {
  padding: 7px 14px; border: 1px solid var(--gray-300); border-radius: var(--radius-sm);
  font-size: 0.8rem; color: var(--gray-700); background: var(--white);
  cursor: pointer; font-family: var(--font-sans);
  display: flex; align-items: center; gap: 6px; transition: var(--transition);
}
.ctrl-btn:hover { background: var(--gray-100); }
.ctrl-btn.active { background: var(--blue-light); color: var(--blue); border-color: var(--blue); }

/* Filter Panel */
.filter-panel {
  display: none; padding: 16px 20px; border-bottom: 1px solid var(--gray-200);
  background: var(--gray-50);
}
.filter-panel.open { display: block; }
.filter-grid {
  display: grid; grid-template-columns: repeat(auto-fill, minmax(180px, 1fr));
  gap: 16px;
}
.filter-group label {
  display: block; font-size: 0.75rem; font-weight: 600; color: var(--gray-600);
  margin-bottom: 6px; text-transform: uppercase; letter-spacing: 0.5px;
}
.filter-group select, .filter-group input {
  width: 100%; padding: 8px 10px; border: 1px solid var(--gray-300);
  border-radius: var(--radius-sm); font-size: 0.85rem; color: var(--navy);
  background: var(--white); font-family: var(--font-sans);
}
.filter-actions { display: flex; gap: 8px; margin-top: 16px; }

/* Column Panel */
.column-panel {
  display: none; padding: 16px 20px; border-bottom: 1px solid var(--gray-200);
  background: var(--gray-50);
}
.column-panel.open { display: block; }
.column-toggle-grid {
  display: flex; flex-wrap: wrap; gap: 10px;
}
.column-toggle {
  display: flex; align-items: center; gap: 8px;
  padding: 6px 14px; border: 1px solid var(--gray-300); border-radius: 20px;
  font-size: 0.8rem; color: var(--gray-600); cursor: pointer;
  transition: var(--transition); font-family: var(--font-sans);
  background: var(--white);
}
.column-toggle:hover { border-color: var(--blue); }
.column-toggle.checked { background: var(--blue-light); color: var(--blue); border-color: var(--blue); }

/* TABLE */
.table-wrap { overflow-x: auto; }
table {
  width: 100%; border-collapse: collapse;
  font-size: 0.85rem; min-width: 1100px;
}
thead th {
  padding: 12px 14px; text-align: right; font-weight: 600;
  font-size: 0.75rem; color: var(--gray-500); text-transform: uppercase;
  letter-spacing: 0.5px; border-bottom: 2px solid var(--gray-200);
  white-space: nowrap; cursor: pointer; user-select: none;
  transition: color var(--transition);
}
thead th:hover { color: var(--navy); }
thead th.sorted { color: var(--blue); }
thead th:first-child, tbody td:first-child { text-align: center; padding-left: 16px; }
thead th:nth-child(2), tbody td:nth-child(2) { text-align: left; }
tbody td {
  padding: 12px 14px; text-align: right;
  border-bottom: 1px solid var(--gray-100);
  white-space: nowrap;
}
tbody tr { transition: background var(--transition); }
tbody tr:hover { background: var(--gray-50); }
tbody tr.highlight { background: var(--blue-light); }
.coin-cell { display: flex; align-items: center; gap: 10px; }
.coin-icon {
  width: 28px; height: 28px; border-radius: 50%;
  display: flex; align-items: center; justify-content: center;
  font-size: 0.7rem; font-weight: 700; color: white;
  flex-shrink: 0;
}
.coin-name { font-weight: 600; color: var(--navy); }
.coin-symbol { font-size: 0.75rem; color: var(--gray-500); }
.rank-num { font-size: 0.8rem; color: var(--gray-500); font-family: var(--font-mono); }
.change-up { color: var(--green); font-weight: 500; }
.change-down { color: var(--red); font-weight: 500; }
.change-neutral { color: var(--gray-500); }
.supply { color: var(--gray-700); }

/* Sparkline */
.sparkline { display: inline-flex; align-items: flex-end; gap: 1px; height: 32px; }
.sparkline svg { width: 80px; height: 28px; }

/* Pagination */
.pagination-bar {
  display: flex; align-items: center; justify-content: space-between;
  padding: 14px 20px; border-top: 1px solid var(--gray-200);
  flex-wrap: wrap; gap: 12px;
}
.pagination-info { font-size: 0.8rem; color: var(--gray-500); }
.pagination-pages { display: flex; gap: 2px; }
.page-btn {
  min-width: 32px; height: 32px; display: flex; align-items: center; justify-content: center;
  border: 1px solid var(--gray-200); border-radius: var(--radius-sm);
  font-size: 0.8rem; color: var(--gray-600); cursor: pointer;
  background: var(--white); font-family: var(--font-mono); transition: var(--transition);
}
.page-btn:hover { background: var(--gray-100); color: var(--navy); }
.page-btn.active { background: var(--blue); color: white; border-color: var(--blue); }
.page-btn.ellipsis { border: none; cursor: default; color: var(--gray-400); }
.page-btn.ellipsis:hover { background: transparent; }

/* MARKET SUMMARY */
.summary-section {
  margin-top: 20px;
  background: var(--white);
  border: 1px solid var(--gray-200);
  border-radius: var(--radius-lg);
  padding: 24px;
}
.summary-title { font-size: 1.1rem; font-weight: 700; color: var(--navy); margin-bottom: 14px; }
.summary-text { font-size: 0.9rem; color: var(--gray-700); line-height: 1.7; }
.summary-text strong { color: var(--navy); }
.summary-extra { display: none; margin-top: 14px; }
.summary-extra.open { display: block; }
.read-more-btn {
  display: inline-flex; align-items: center; gap: 4px;
  color: var(--blue); font-weight: 600; cursor: pointer;
  font-size: 0.85rem; margin-top: 12px; background: none; border: none;
  font-family: var(--font-sans);
}
.read-more-btn:hover { color: var(--blue-hover); }
.read-more-btn svg { transition: transform var(--transition); }
.read-more-btn.open svg { transform: rotate(180deg); }

/* INFO CONTENT */
.info-section {
  margin-top: 20px;
  display: grid; grid-template-columns: repeat(2, 1fr);
  gap: 20px;
}
.info-card {
  background: var(--white);
  border: 1px solid var(--gray-200);
  border-radius: var(--radius-lg);
  padding: 24px;
}
.info-card h3 { font-size: 0.95rem; font-weight: 700; color: var(--navy); margin-bottom: 10px; }
.info-card p { font-size: 0.85rem; color: var(--gray-600); line-height: 1.6; }

/* FOOTER */
.footer {
  margin-top: 40px;
  background: var(--navy);
  color: var(--gray-400);
  padding: 40px 0 24px;
}
.footer-grid {
  display: grid; grid-template-columns: repeat(4, 1fr);
  gap: 32px; padding-bottom: 32px;
  border-bottom: 1px solid rgba(255,255,255,0.1);
}
.footer-col h4 {
  font-size: 0.85rem; font-weight: 700; color: white;
  margin-bottom: 14px; text-transform: uppercase; letter-spacing: 0.5px;
}
.footer-col ul { list-style: none; }
.footer-col ul li { margin-bottom: 8px; }
.footer-col ul li a { color: var(--gray-400); font-size: 0.85rem; transition: var(--transition); }
.footer-col ul li a:hover { color: white; }
.footer-bottom {
  display: flex; justify-content: space-between; align-items: center;
  padding-top: 20px; font-size: 0.8rem;
}

/* SELECT/INPUT GLOBAL */
select:focus, input:focus, button:focus { outline: 2px solid var(--blue); outline-offset: 2px; }

/* RESPONSIVE */
@media (max-width: 1200px) {
  .metrics-grid { grid-template-columns: repeat(4, 1fr); }
  .nav-links { display: none; }
  .info-section { grid-template-columns: 1fr; }
  .footer-grid { grid-template-columns: repeat(2, 1fr); }
}
@media (max-width: 768px) {
  .metrics-grid { grid-template-columns: repeat(2, 1fr); }
  .metric-card:nth-child(2n) { border-right: none; }
  .footer-grid { grid-template-columns: 1fr 1fr; }
  .pagination-bar { flex-direction: column; align-items: flex-start; }
  .table-header { flex-direction: column; align-items: flex-start; }
  .index-row { flex-wrap: wrap; gap: 12px; }
  .ai-inner { flex-direction: column; align-items: flex-start; }
}
@media (max-width: 480px) {
  .metrics-grid { grid-template-columns: 1fr; }
  .metric-card { border-right: none; border-bottom: 1px solid var(--gray-200); }
  .nav-cta { gap: 6px; }
  .btn { padding: 6px 10px; font-size: 0.75rem; }
}
</style>
</head>
