// ============ HELPERS ============
function formatPrice(n) {
  if (n >= 1) return '$' + n.toLocaleString('en-US', { minimumFractionDigits: 2, maximumFractionDigits: 2 });
  if (n >= 0.01) return '$' + n.toFixed(4);
  if (n >= 0.0001) return '$' + n.toFixed(6);
  return '$' + n.toFixed(10);
}

function formatMcap(n) {
  if (n >= 1e12) return '$' + (n / 1e12).toFixed(2) + 'T';
  if (n >= 1e9) return '$' + (n / 1e9).toFixed(2) + 'B';
  if (n >= 1e6) return '$' + (n / 1e6).toFixed(2) + 'M';
  return '$' + n.toLocaleString();
}

function formatVolume(n) {
  if (n >= 1e9) return '$' + (n / 1e9).toFixed(2) + 'B';
  if (n >= 1e6) return '$' + (n / 1e6).toFixed(2) + 'M';
  return '$' + (n / 1e3).toFixed(2) + 'K';
}

function formatChange(n) {
  const s = (n >= 0 ? '+' : '') + n.toFixed(2) + '%';
  if (n > 0) return `<span class="change-up">${s}</span>`;
  if (n < 0) return `<span class="change-down">${s}</span>`;
  return `<span class="change-neutral">${s}</span>`;
}

function getChangeClass(n) {
  return n > 0 ? 'up' : n < 0 ? 'down' : '';
}

function generateSparkline(change7d) {
  const points = 7;
  const trend = change7d > 0 ? 1 : -1;
  const vals = [];
  let base = 0.3;
  for (let i = 0; i < points; i++) {
    const t = i / (points - 1);
    const progress = trend > 0 ? t : (1 - t);
    const noise = (Math.random() - 0.5) * 0.25;
    vals.push(Math.max(0.05, Math.min(0.95, base + (0.6 * progress) + noise)));
    base = vals[vals.length - 1];
  }
  const max = Math.max(...vals);
  const min = Math.min(...vals);
  const range = max - min || 1;
  const h = 28, w = 80, pad = 2;
  const pts = vals.map((v, i) => ({
    x: pad + (i / (points - 1)) * (w - 2 * pad),
    y: pad + (1 - (v - min) / range) * (h - 2 * pad)
  }));
  const d = pts.map((p, i) => (i === 0 ? 'M' : 'L') + p.x.toFixed(1) + ',' + p.y.toFixed(1)).join(' ');
  const color = change7d >= 0 ? '#16c784' : '#ea3943';
  return `<svg width="${w}" height="${h}" viewBox="0 0 ${w} ${h}"><path d="${d}" fill="none" stroke="${color}" stroke-width="1.5" stroke-linecap="round" stroke-linejoin="round"/></svg>`;
}

// ============ RENDER ============
function getFilteredData() {
  let data = [...coinData];

  if (state.activeCategory !== 'top') {
    data = data.filter(c => c.category === state.activeCategory);
  }

  if (state.activeNetwork !== 'all') {
    data = data.filter(c => c.network === state.activeNetwork);
  }

  // Apply user filters
  const f = state.activeFilters;
  if (f.price) {
    if (f.price === 'lt1') data = data.filter(c => c.price < 1);
    else if (f.price === '1to100') data = data.filter(c => c.price >= 1 && c.price <= 100);
    else if (f.price === '100to1000') data = data.filter(c => c.price > 100 && c.price <= 1000);
    else if (f.price === 'gt1000') data = data.filter(c => c.price > 1000);
  }
  if (f.mcap) {
    if (f.mcap === 'lt1b') data = data.filter(c => c.marketCap < 1e9);
    else if (f.mcap === '1bto10b') data = data.filter(c => c.marketCap >= 1e9 && c.marketCap <= 1e10);
    else if (f.mcap === '10bto100b') data = data.filter(c => c.marketCap > 1e10 && c.marketCap <= 1e11);
    else if (f.mcap === 'gt100b') data = data.filter(c => c.marketCap > 1e11);
  }
  if (f.change24h) {
    if (f.change24h === 'up') data = data.filter(c => c.change24h > 0);
    else if (f.change24h === 'down') data = data.filter(c => c.change24h < 0);
  }
  if (f.change7d) {
    if (f.change7d === 'up') data = data.filter(c => c.change7d > 0);
    else if (f.change7d === 'down') data = data.filter(c => c.change7d < 0);
  }

  return data;
}

function sortData(data) {
  const k = state.sortKey;
  const d = state.sortDir === 'asc' ? 1 : -1;
  return data.sort((a, b) => {
    let va, vb;
    if (k === 'name') { va = a.name; vb = b.name; return d * va.localeCompare(vb); }
    if (k === 'rank') return d * (a.marketCap - b.marketCap); // rank = marketCap desc
    if (k === 'supply') { va = a.supplyVal; vb = b.supplyVal; }
    else { va = a[k]; vb = b[k]; }
    return d * (va - vb);
  });
}

function renderTable() {
  let data = getFilteredData();
  data = sortData(data);
  const total = data.length;
  const start = (state.currentPage - 1) * state.rowsPerPage;
  const pageData = data.slice(start, start + state.rowsPerPage);

  // Re-rank
  const rankedData = pageData.map((coin, i) => ({ ...coin, displayRank: start + i + 1 }));

  const tbody = document.getElementById('tableBody');
  tbody.innerHTML = rankedData.map(coin => `
    <tr>
      ${state.visibleCols.rank ? `<td><span class="rank-num">${coin.displayRank}</span></td>` : ''}
      ${state.visibleCols.name ? `<td><div class="coin-cell"><div class="coin-icon" style="background:${coinColors[(coin.displayRank - 1) % coinColors.length]}">${coin.symbol[0]}</div><div><div class="coin-name">${coin.name}</div><div class="coin-symbol">${coin.symbol}</div></div></div></td>` : ''}
      ${state.visibleCols.price ? `<td class="price">${formatPrice(coin.price)}</td>` : ''}
      ${state.visibleCols.change1h ? `<td class="tabular">${formatChange(coin.change1h)}</td>` : ''}
      ${state.visibleCols.change24h ? `<td class="tabular">${formatChange(coin.change24h)}</td>` : ''}
      ${state.visibleCols.change7d ? `<td class="tabular">${formatChange(coin.change7d)}</td>` : ''}
      ${state.visibleCols.marketCap ? `<td class="tabular">${formatMcap(coin.marketCap)}</td>` : ''}
      ${state.visibleCols.volume ? `<td class="tabular">${formatVolume(coin.volume)}</td>` : ''}
      ${state.visibleCols.supply ? `<td class="supply">${coin.supply}</td>` : ''}
      ${state.visibleCols.sparkline ? `<td><div class="sparkline">${generateSparkline(coin.change7d)}</div></td>` : ''}
    </tr>
  `).join('');

  // Update pagination info
  document.getElementById('paginationInfo').textContent =
    `Showing ${start + 1}–${Math.min(start + state.rowsPerPage, total)} of ${total.toLocaleString()} assets`;

  renderPagination(data.length);
  updateSortIndicator();
}

function renderPagination(totalItems) {
  const totalP = Math.ceil(totalItems / state.rowsPerPage);
  const current = state.currentPage;
  const pages = document.getElementById('paginationPages');

  let html = '';
  html += `<button class="page-btn" onclick="goToPage(${current - 1})" ${current === 1 ? 'disabled style="opacity:0.4"' : ''}>◂</button>`;

  const maxShow = 7;
  let startPage = Math.max(1, current - Math.floor(maxShow / 2));
  let endPage = Math.min(totalP, startPage + maxShow - 1);
  if (endPage - startPage < maxShow - 1) startPage = Math.max(1, endPage - maxShow + 1);

  if (startPage > 1) {
    html += `<button class="page-btn" onclick="goToPage(1)">1</button>`;
    if (startPage > 2) html += `<span class="page-btn ellipsis">…</span>`;
  }

  for (let i = startPage; i <= endPage; i++) {
    html += `<button class="page-btn ${i === current ? 'active' : ''}" onclick="goToPage(${i})">${i}</button>`;
  }

  if (endPage < totalP) {
    if (endPage < totalP - 1) html += `<span class="page-btn ellipsis">…</span>`;
    html += `<button class="page-btn" onclick="goToPage(${totalP})">${totalP}</button>`;
  }

  html += `<button class="page-btn" onclick="goToPage(${current + 1})" ${current === totalP ? 'disabled style="opacity:0.4"' : ''}>▸</button>`;
  pages.innerHTML = html;
}

function goToPage(p) {
  const data = getFilteredData();
  const totalP = Math.ceil(data.length / state.rowsPerPage);
  if (p < 1 || p > totalP) return;
  state.currentPage = p;
  renderTable();
  document.querySelector('.table-section').scrollIntoView({ behavior: 'smooth', block: 'start' });
}

function updateSortIndicator() {
  document.querySelectorAll('thead th').forEach(th => {
    th.classList.remove('sorted');
    if (th.dataset.sort === state.sortKey) th.classList.add('sorted');
  });
}

function setSort(key) {
  if (state.sortKey === key) {
    state.sortDir = state.sortDir === 'asc' ? 'desc' : 'asc';
  } else {
    state.sortKey = key;
    state.sortDir = key === 'rank' || key === 'marketCap' || key === 'volume' ? 'desc' : 'asc';
  }
  state.currentPage = 1;
  renderTable();
}

function handleSort() {
  const sel = document.getElementById('sortSelect').value;
  state.sortKey = sel;
  state.sortDir = sel === 'change24h' || sel === 'change7d' ? 'desc' : 'desc';
  state.currentPage = 1;
  renderTable();
}

