    state.activeCategory = e.target.dataset.cat;
    state.currentPage = 1;
    renderTable();
  }
});

// ============ PANELS ============
function togglePanel(panelId) {
  const panel = document.getElementById(panelId);
  const isOpen = panel.classList.contains('open');

  // Close both panels
  document.getElementById('filterPanel').classList.remove('open');
  document.getElementById('columnPanel').classList.remove('open');
  document.getElementById('filtersBtn').classList.remove('active');
  document.getElementById('columnsBtn').classList.remove('active');

  if (!isOpen) {
    panel.classList.add('open');
    if (panelId === 'filterPanel') document.getElementById('filtersBtn').classList.add('active');
    if (panelId === 'columnPanel') document.getElementById('columnsBtn').classList.add('active');
  }
}

function toggleColumn(el) {
  const col = el.dataset.col;
  state.visibleCols[col] = el.checked;
  el.parentElement.classList.toggle('checked', el.checked);
  renderTable();
}

function applyFilters() {
  state.activeFilters = {
    price: document.getElementById('filterPrice').value,
    mcap: document.getElementById('filterMcap').value,
    change24h: document.getElementById('filter24h').value,
    change7d: document.getElementById('filter7d').value
  };
  state.currentPage = 1;
  // Filter out empty
  Object.keys(state.activeFilters).forEach(k => {
    if (!state.activeFilters[k]) delete state.activeFilters[k];
  });
  renderTable();
  togglePanel('filterPanel');
}

function clearFilters() {
  document.querySelectorAll('#filterPanel select').forEach(s => s.value = '');
  state.activeFilters = {};
  state.currentPage = 1;
  renderTable();
}

// ============ PROMO CAROUSEL ============
function navigatePromo(dir) {
  state.promoIndex = ((state.promoIndex + dir) % promos.length + promos.length) % promos.length;
  updatePromo();
}

function updatePromo() {
  document.getElementById('promoContent').querySelector('.promo-text').textContent = promos[state.promoIndex];
  const dots = document.getElementById('promoDots');
  dots.innerHTML = promos.map((_, i) =>
    `<span class="promo-dot ${i === state.promoIndex ? 'active' : ''}"></span>`
  ).join('');
}

// Auto rotate promo
setInterval(() => { state.promoIndex = (state.promoIndex + 1) % promos.length; updatePromo(); }, 5000);

// ============ MARKET SUMMARY ACCORDION ============
function toggleSummary() {
  const extra = document.getElementById('summaryExtra');
  const btn = document.getElementById('readMoreBtn');
  extra.classList.toggle('open');
  btn.classList.toggle('open');
  btn.querySelector('span').textContent = extra.classList.contains('open') ? 'Read Less' : 'Read More';
}

// ============ INIT ============
function init() {
  updatePromo();
  renderTable();

  // Configure sort dropdown to match
  document.getElementById('sortSelect').value = 'marketCap';
}

init();
</script>
</body>
</html>
